  await env.DB.batch([
    q("DELETE FROM session WHERE userId = ?", userId),
    q("DELETE FROM account WHERE userId = ?", userId),
    q('DELETE FROM "user" WHERE id = ?', userId),
  ]);
  return { ok: true };
}

