  if ((!res || res.status >= 500) && retry && !state.snap) {
    await new Promise((r) => setTimeout(r, 400));
    if (seq !== refreshSeq) return;
    return refresh(orgId, false);
  }
  if (!res) {
    if (!state.snap) set({ loadError: "The console couldn't load." });
    return;
